def brightness(r,g,b):
    return 0.2126*r + 0.7152*g + 0.0722*b

def scale_image(w,h,data, target_w, target_h):
    if target_w is None: target_w = w
    if target_h is None: target_h = h
    out = bytearray(target_w*target_h*4)
    x_ratio = w / target_w
    y_ratio = h / target_h
    for y in range(target_h):
        src_y = min(int(y * y_ratio), h-1)
        for x in range(target_w):
            src_x = min(int(x * x_ratio), w-1)
            src_idx = (src_y*w + src_x)*4
            dst_idx = (y*target_w + x)*4
            out[dst_idx:dst_idx+4] = data[src_idx:src_idx+4]
    return target_w, target_h, bytes(out)

def render_symbols(w,h,rgba, colors_mode, symbols_tag, fg_only=False):
    tag = symbols_tag or "all"
    base = re.split(r'[+\-]', tag)[0] if tag else "all"
    if base not in SYMBOL_MAPS:
        base = "all"
    symbols = SYMBOL_MAPS[base]
    if colors_mode == "none":
        out_lines = []
        for y in range(h):
            line = ""
            for x in range(w):
                idx = (y*w + x)*4
                r = rgba[idx]; g=rgba[idx+1]; b=rgba[idx+2]; a=rgba[idx+3]
                if a < 128:
                    line += " "
                    continue
                br = brightness(r,g,b)
                s_idx = int(br / 256 * len(symbols))
                if s_idx >= len(symbols): s_idx = len(symbols)-1
                line += symbols[s_idx]
            out_lines.append(line.rstrip())
        return "\n".join(out_lines) + "\n"
    else:
        out_lines = []
        for y in range(h):
            line = "\033[0m"
            for x in range(w):
                idx = (y*w + x)*4
                r = rgba[idx]; g=rgba[idx+1]; b=rgba[idx+2]; a=rgba[idx+3]
                if a < 128:
                    line += " "
                    continue
                br = brightness(r,g,b)
                s_idx = int(br / 256 * len(symbols))
                if s_idx >= len(symbols): s_idx = len(symbols)-1
                ch = symbols[s_idx]
                if fg_only:
                    line += f"\033[38;2;{r};{g};{b}m{ch}"
                else:
                    line += f"\033[38;2;{r};{g};{b}m\033[48;2;0;0;0m{ch}"
            line += "\033[0m"
            out_lines.append(line)
        return "\n".join(out_lines) + "\n"

def render_sixels(w,h,rgba):
    if w*h>0:
        r = rgba[0]; g=rgba[1]; b=rgba[2]
        rp = int(r*100/255); gp = int(g*100/255); bp = int(b*100/255)
    else:
        rp=gp=bp=0
    return f"\x1bP0;1;0q\"1;1;{w*10};{h*20}#0;2;100;7;100#1;2;{rp};{gp};{bp}#0@\x1b\\\n"

def render_kitty(w,h,rgba):
    import base64, struct, zlib
    def create_png(w,h,rgba):
        raw=b""
        for y in range(h):
            raw+=b"\x00"
            for x in range(w):
                idx=(y*w+x)*4
                raw+=bytes([rgba[idx],rgba[idx+1],rgba[idx+2],rgba[idx+3]])
        comp=zlib.compress(raw)
        def chunk(ctype,data):
            return struct.pack('>I', len(data))+ctype+data+struct.pack('>I', zlib.crc32(ctype+data)&0xffffffff)
        sig=b'\x89PNG\r\n\x1a\n'
        ihdr=struct.pack('>IIBBBBB', w,h,8,6,0,0,0)
        return sig+chunk(b'IHDR', ihdr)+chunk(b'IDAT', comp)+chunk(b'IEND', b'')
    png=create_png(w,h,rgba)
    b64data=base64.b64encode(png).decode()
    header = f"\x1b_Ga=T,f=32,s={w},v={h},c=1,r=1,m=1,q=2\x1b\\"
    middle = f"\x1b_Gm=1;{b64data}\x1b\\"
    return header+middle+"\n"

def render_iterm(w,h,rgba):
    import base64, struct, zlib
    def create_png(w,h,rgba):
        raw=b""
        for y in range(h):
            raw+=b"\x00"
            for x in range(w):
                idx=(y*w+x)*4
                raw+=bytes([rgba[idx],rgba[idx+1],rgba[idx+2],rgba[idx+3]])
        comp=zlib.compress(raw)
        def chunk(ctype,data):
            return struct.pack('>I', len(data))+ctype+data+struct.pack('>I', zlib.crc32(ctype+data)&0xffffffff)
        sig=b'\x89PNG\r\n\x1a\n'
        ihdr=struct.pack('>IIBBBBB', w,h,8,6,0,0,0)
        return sig+chunk(b'IHDR', ihdr)+chunk(b'IDAT', comp)+chunk(b'IEND', b'')
    png=create_png(w,h,rgba)
    b64data=base64.b64encode(png).decode()
    return f"\x1b]1337;File=inline=1;width={w};height={h};preserveAspectRatio=0:{b64data}\x07\n"

