                            help_flag=True
                        elif long_name == "grid":
                            opts["grid"]="auto"
                        elif long_name == "label":
                            opts["label"]="on"
                    i+=1
                else:
                    ch = chars[0]
                    if ch not in short_map:
                        error_exit(f"{PROG}: Unknown option -{ch}\n")
                    long_name, req = short_map[ch]
                    if req == "flag":
                        error_exit(f"{PROG}: Unknown option -{ch}\n")
                    else:
                        if i+1 >= n:
                            error_exit(f"{PROG}: Missing argument for -{ch}\n")
                        val = argv[i+1]
                        opts[long_name]=val
                        i+=2
        else:
            positional.append(arg)
